G=load()
def comps(g):
    seen=set(); out=[]
    for i,r in enumerate(g):
        for j,v in enumerate(r):
            if v and (i,j) not in seen:
                q=[(i,j)];seen.add((i,j));c=[]
                while q:
                    y,x=q.pop();c.append((y,x))
                    for dy,dx in((1,0),(-1,0),(0,1),(0,-1)):
                        a,b=y+dy,x+dx
                        if 0<=a<len(g) and 0<=b<len(g[0]) and g[a][b] and (a,b) not in seen:
