    ts=[yy for yy in cnt if cnt[yy]==1]
    o='U' if min(ts)<b else 'D'
    return dict(trow=min(ts),bar=b,my=min(ys),My=max(ys),mx=min(xs),Mx=max(xs),o=o,n=len(c),H=H,W=W)
